SELECT * FROM ( SELECT '02' dataStatus , i.ASSET_UUID, i.asset_name, i.asset_code, i.asset_type, i.asset_type2, i.org_asset_type1, i.org_asset_type2, i.org_asset_type3, DATE_FORMAT(i.vdate,'%Y-%m-%d') vDateStr, DATE_FORMAT(i.mdate,'%Y-%m-%d') mDateStr, null ERRMSG FROM chb_asset_info i WHERE 1=1 and i.status in ('E','M')
#{item}
#{item}
#{item}
#{item}
#{item}
and 1=2
AND ASSET_UUID = #{Assetuuid}
and not exists ( SELECT 1 FROM CHB_ASSET_INFO_ERRODATA IE WHERE IE.asset_code = i.asset_code )
UNION ALL SELECT '01' dataStatus, e.DATAUUID ASSET_UUID, e.asset_name, e.asset_code, e.asset_type, e.asset_type2, e.org_asset_type1, e.org_asset_type2, e.org_asset_type3, e.vdate vDateStr, e.mdate mDateStr, E.ERR_MSG FROM CHB_ASSET_INFO_ERRODATA e WHERE 1=1 and e.status in ('E','M')
#{item}
#{item}
#{item}
#{item}
#{item}
and 1=2
AND DATAUUID = #{Assetuuid}
) t ORDER BY dataStatus DESC

SELECT DISTINCT ASSET_CODE id, ifnull(ASSET_NAME,ASSET_CODE) text from ( SELECT ASSET_CODE,ASSET_NAME FROM CHB_ASSET_INFO ASSETINFO
1=1 and ASSETINFO.STATUS IN ('E','M')
and ASSETINFO.ASSET_CODE like concat('%', #{search},'%') or ASSETINFO.ASSET_NAME like concat('%', #{search},'%')
#{orgCode}
union all
SELECT ASSET_CODE,ASSET_NAME FROM CHB_ASSET_INFO_ERRODATA data
and data.ASSET_CODE like concat('%', #{search},'%') or data.ASSET_NAME like concat('%', #{search},'%')
#{orgCode}
) t ORDER BY ASSET_CODE

SELECT * FROM SYS_DATADICT_LIST_LINK
WHERE 1=1

    and LINKED_DICT_CODE = #{linkDictCode}


    and LINKED_ITEM_CODE = #{linkItemCode}

SELECT * FROM CHB_ASSET_INFO
where ASSET_UUID = #{Assetuuid}
and STATUS IN ('E','M')

SELECT E.CHB_ASSET_TYPE2 id, l.ITEM_VALUE text
FROM CHB_ASSET_TYPE_MAPPING_EX E
left join CHB_ASSET_TYPE_MAPPING M ON E.MAPPING_UUID = M.TYPEUUID
LEFT JOIN SYS_DATADICT_LIST L ON L.DICT_CODE = 'SVR_ASSET_TYPE_SECOND_LEVEL' AND E.CHB_ASSET_TYPE2 = L.ITEM_CODE
WHERE
M.ASSET_TYPE1 = #{orgAssetType1}

    AND M.ASSET_TYPE2 =#{orgAssetType2}


    AND M.ASSET_TYPE3 =#{orgAssetType3}


    AND M.ASSET_BUSI_TYPE =#{orgAssetType4}


    AND (E.CHB_ASSET_TYPE2 like (concat_ws('%', #{search}),'%')
    or l.ITEM_VALUE like (concat_ws('%', #{search}),'%') )

SELECT '02' dataStatus ,
i.*,
null   ERRMSG
